// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-time-picker.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The live region of `politeness` in the shadow root of `el`. */
function annRegion(el: HTMLElement, politeness: 'polite' | 'assertive') {
  return el.shadowRoot!.querySelector<HTMLElement>(`[data-announcer="${politeness}"]`);
}

/** Waits (at most a second) until the live region holds `expected`, and returns its text. */
async function annText(el: HTMLElement, politeness: 'polite' | 'assertive', expected: string) {
  const text = () => annRegion(el, politeness)?.textContent?.trim() ?? '';
  // Checks once per frame (the shared until() helper, inlined).
  const end = performance.now() + 1000;
  while (text() !== expected && performance.now() < end) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
  return text();
}

describe('<md-gb-time-picker> announcer contract (AnnouncerController)', () => {
  afterEach(() => container?.remove());

  it('announces the minutes politely when Enter moves the selection on, without moving focus off the dial', async () => {
    // spec: time-pickers-4d5943, time-pickers-22d7af
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-time-picker value="14:30" hour-cycle="12" quick></md-gb-time-picker>
    `);
    const el = root.querySelector<any>('md-gb-time-picker')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    const dial = el.shadowRoot.querySelector('.time-picker-dial') as HTMLElement;
    dial.focus();
    await press('Enter');
    const expected = 'Select minutes';
    expect(expected).not.toBe('');
    expect(await annText(el, 'polite', expected)).toBe(expected);
    const region = annRegion(el, 'polite')!;
    expect(region.getAttribute('role')).toBe('status');
    expect(region.getAttribute('aria-live')).toBe('polite');
    expect(region.getAttribute('aria-atomic')).toBe('true');
  });

  it('removes its live regions when it disconnects', async () => {
    const root = await mount(html`<md-gb-time-picker value="14:30" hour-cycle="12" quick></md-gb-time-picker>`);
    const el = root.querySelector<any>('md-gb-time-picker')!;
    const dial = el.shadowRoot.querySelector('.time-picker-dial') as HTMLElement;
    dial.focus();
    await press('Enter');
    await annText(el, 'polite', 'Select minutes');
    expect(el.shadowRoot.querySelector('[data-announcer]')).not.toBeNull();
    el.remove();
    await settle();
    expect(el.shadowRoot.querySelector('[data-announcer]')).toBeNull();
  });
});

/** The form's entries, as submitted. */
function submittedEntries(form: HTMLFormElement) {
  return [...new FormData(form).entries()].map(([k, v]) => [k, String(v)]);
}

async function setupFormPicker(attrs: Record<string, string> = {}) {
  const root = await mount(html`
    <form>
      <fieldset>
        <md-gb-time-picker name="when" modal quick mode="input"></md-gb-time-picker>
      </fieldset>
    </form>
  `);
  const el = root.querySelector<any>('md-gb-time-picker')!;
  for (const [name, value] of Object.entries(attrs)) el.setAttribute(name, value);
  await settle();
  return {
    el,
    form: root.querySelector('form')!,
    fieldset: root.querySelector('fieldset')!,
  };
}

/** Picks a different value with real keys. */
async function pickFormPicker(f: {el: any}) {
  await f.el.show();
  await settle();
  await press('ArrowUp');
  await press('Enter');
  await settle();
}

describe('<md-gb-time-picker> form contract (shared form layer)', () => {
  afterEach(() => container?.remove());

  it('submits the picked value under its name, and nothing before', async () => {
    const f = await setupFormPicker();
    expect(f.el.value).toBe('');
    expect(submittedEntries(f.form)).toEqual([]);
    await pickFormPicker(f);
    expect(f.el.value).not.toBe('');
    expect(submittedEntries(f.form)).toEqual([['when', f.el.value]]);
  });

  it('starts on the value attribute and resets to it', async () => {
    const f = await setupFormPicker({value: '09:30'});
    expect(f.el.value).toBe('09:30');
    expect(submittedEntries(f.form)).toEqual([['when', '09:30']]);
    await pickFormPicker(f);
    expect(f.el.value).not.toBe('09:30');
    f.form.reset();
    await settle();
    expect(f.el.value).toBe('09:30');
    expect(submittedEntries(f.form)).toEqual([['when', '09:30']]);
  });

  it('restores the saved value', async () => {
    const f = await setupFormPicker();
    f.el.formStateRestoreCallback('09:30', 'restore');
    await settle();
    expect(f.el.value).toBe('09:30');
    expect(submittedEntries(f.form)).toEqual([['when', '09:30']]);
  });

  it('is invalid while required and empty, valid once picked', async () => {
    const f = await setupFormPicker({required: ''});
    expect(f.el.validity.valueMissing).toBeTrue();
    expect(f.form.checkValidity()).toBeFalse();
    await pickFormPicker(f);
    expect(f.el.validity.valid).toBeTrue();
    expect(f.form.checkValidity()).toBeTrue();
  });

  it('setCustomValidity() invalidates until cleared', async () => {
    const f = await setupFormPicker();
    f.el.setCustomValidity('Not available');
    expect(f.el.validity.customError).toBeTrue();
    expect(f.el.validationMessage).toBe('Not available');
    expect(f.form.checkValidity()).toBeFalse();
    f.el.setCustomValidity('');
    expect(f.el.validity.valid).toBeTrue();
  });

  it('blocks a submit while invalid and lets it through once valid', async () => {
    const f = await setupFormPicker({required: ''});
    let submitted = 0;
    f.form.addEventListener('submit', (e) => {
      e.preventDefault();
      submitted++;
    });
    f.form.requestSubmit();
    expect(submitted).toBe(0);
    await pickFormPicker(f);
    f.form.requestSubmit();
    expect(submitted).toBe(1);
  });

  it('reportValidity() fires invalid and reports false while required and empty', async () => {
    const f = await setupFormPicker({required: ''});
    let invalid = 0;
    f.el.addEventListener('invalid', () => invalid++);
    expect(f.el.reportValidity()).toBeFalse();
    expect(invalid).toBe(1);
    await pickFormPicker(f);
    expect(f.el.reportValidity()).toBeTrue();
    expect(invalid).toBe(1);
  });

  it('follows a disabled fieldset, is left out of the form and recovers', async () => {
    const f = await setupFormPicker({value: '09:30'});
    expect(f.el.disabled).toBeFalse();
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.disabled).toBeTrue();
    expect(submittedEntries(f.form)).toEqual([]);
    f.fieldset.disabled = false;
    await settle();
    expect(f.el.disabled).toBeFalse();
    expect(submittedEntries(f.form)).toEqual([['when', '09:30']]);
  });

  it('is not validated while disabled', async () => {
    const f = await setupFormPicker({required: ''});
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.willValidate).toBeFalse();
    expect(f.form.checkValidity()).toBeTrue();
  });
});

import {resetEscapeTracking} from '../../foundations/interaction/gestures/predictive-back.js';

/** What the lifecycle surfaces share: `show()`, `close()`, `open` and events. */
interface ModalLifecycleElement extends HTMLElement {
  open: boolean;
  show(): Promise<void>;
  close(...args: string[]): Promise<void>;
}

/** Records open / opened / close / closed, with `:reason` for close events. */
function modalRecord(el: HTMLElement) {
  const log: string[] = [];
  for (const type of ['open', 'opened', 'close', 'closed']) {
    el.addEventListener(type, (event) => {
      const reason = (event as CustomEvent).detail?.reason;
      log.push(reason ? `${type}:${reason}` : type);
    });
  }
  return log;
}

function modalOnce(el: HTMLElement, type: string) {
  return new Promise<void>((resolve) =>
    el.addEventListener(type, () => resolve(), {once: true}),
  );
}

/**
 * A close request counts as Escape for a second after an Escape press (the
 * browser reports Escape and the back gesture alike). Forgets the recorded
 * presses, so the next close request is a back request.
 */
function modalForgetEscape() {
  resetEscapeTracking();
}

/** Whether the page scroll is locked (CSS overflow of the root element). */
function modalPageLocked() {
  return getComputedStyle(document.documentElement).overflow === 'hidden';
}

async function setupModalTimePicker(opts: {standard?: boolean} = {}) {
  const root = await mount(opts.standard ? html`<button id="before">Before</button><md-gb-time-picker quick></md-gb-time-picker>` : html`<button id="before">Before</button><md-gb-time-picker modal quick></md-gb-time-picker>`);
  const el = root.querySelector<ModalLifecycleElement>('md-gb-time-picker')!;
  await settle();
  return {el, before: root.querySelector<HTMLElement>('#before')!};
}

async function openModalTimePicker(el: ModalLifecycleElement) {
  await el.show();
  await settle();
}

function isOpenModalTimePicker(el: ModalLifecycleElement) {
  return el.open;
}

describe('<md-gb-time-picker> modal surface contract (modal time picker; ModalSurfaceController)', () => {
  afterEach(() => container?.remove());

  it('fires open and opened when it opens, and open can be canceled', async () => {
    const {el} = await setupModalTimePicker();
    const log = modalRecord(el);
    await el.show();
    expect(log).toEqual(['open', 'opened']);
    expect(el.open).toBeTrue();
    await el.close();
    const canceled = await setupModalTimePicker();
    canceled.el.addEventListener('open', (event) => event.preventDefault());
    await canceled.el.show();
    expect(canceled.el.open).toBeFalse();
  });

  it('fires a cancelable close and closed with detail.reason, and stays open when close is canceled', async () => {
    const {el} = await setupModalTimePicker();
    await el.show();
    const log = modalRecord(el);
    await el.close('custom');
    expect(log).toEqual(['close:custom', 'closed:custom']);
    expect(el.open).toBeFalse();
    await el.show();
    el.addEventListener('close', (event) => event.preventDefault(), {once: true});
    await el.close();
    expect(el.open).toBeTrue();
  });

  it('closes on Escape with the escape reason', async () => {
    const {el} = await setupModalTimePicker();
    await openModalTimePicker(el);
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(isOpenModalTimePicker(el)).toBeFalse();
    expect(log).toEqual(['close:escape', 'closed:escape']);
  });

  it('closes on a scrim click with the scrim reason', async () => {
    // spec: time-pickers-7b8acb
    const {el} = await setupModalTimePicker();
    await openModalTimePicker(el);
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    el.shadowRoot!.querySelector('dialog')!.click();
    await closed;
    expect(isOpenModalTimePicker(el)).toBeFalse();
    expect(log).toEqual(['close:scrim', 'closed:scrim']);
  });

  it('closes on a back request with the back reason', async () => {
    const {el} = await setupModalTimePicker();
    await openModalTimePicker(el);
    const dialog = el.shadowRoot!.querySelector('dialog')!;
    if (typeof dialog.requestClose !== 'function') {
      pending('HTMLDialogElement.requestClose() is not supported');
    }
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    await modalForgetEscape();
    dialog.requestClose();
    await closed;
    expect(isOpenModalTimePicker(el)).toBeFalse();
    expect(log).toEqual(['close:back', 'closed:back']);
  });

  it('moves focus into the surface when it opens and restores it when it closes', async () => {
    // spec: time-pickers-0ae5d3
    const {el, before} = await setupModalTimePicker();
    before.focus();
    await openModalTimePicker(el);
    expect(el.matches(':focus-within')).withContext('focus is inside').toBeTrue();
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(document.activeElement).toBe(before);
  });

  it('keeps Tab and Shift+Tab inside the surface', async () => {
    // spec: time-pickers-0ae5d3
    const {el} = await setupModalTimePicker();
    await openModalTimePicker(el);
    for (let i = 0; i < 6; i++) {
      await press('Tab');
      expect(el.matches(':focus-within')).withContext(`after Tab ${i + 1}`).toBeTrue();
    }
    for (let i = 0; i < 6; i++) {
      await press('Shift+Tab');
      expect(el.matches(':focus-within')).withContext(`after Shift+Tab ${i + 1}`).toBeTrue();
    }
  });

  it('locks page scrolling while it is open, and releases the lock when it closes', async () => {
    // spec: time-pickers-e115c0
    const {el} = await setupModalTimePicker();
    expect(modalPageLocked()).toBeFalse();
    await openModalTimePicker(el);
    expect(modalPageLocked()).toBeTrue();
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(modalPageLocked()).toBeFalse();
  });

  it('standard variant: no scroll lock, no focus move, ignores Escape', async () => {
    const {el, before} = await setupModalTimePicker({standard: true});
    before.focus();
    await openModalTimePicker(el);
    expect(modalPageLocked()).withContext('no scroll lock').toBeFalse();
    expect(document.activeElement).withContext('focus stays').toBe(before);
    await press('Escape');
    await settle();
    expect(isOpenModalTimePicker(el)).withContext('Escape does not close it').toBeTrue();
  });
});
